INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('3a10f60c-5085-4d90-853a-db45f2eaf902','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'sop document','i uploaded a document, a SOP for Equipment Qualification Procedure information. remember it so you can use it later in RAG.','completed','high','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045',NULL,'2025-07-28',ARRAY[]::text[],ARRAY['Annex 11','EU GMP Annex 15','Annex 05','Annex 09','followup-pending','est-hours-unverified','capture-v6','source:chat-extraction','Annex 07','consolidation-2026-06-28','Annex 08','Annex 01','Annex 02','Annex 03','ws:WS-EQ-QUAL','Annex 06','Annex 04','Annex 12','EudraLex','GAMP5','WHO TRS 961']::text[],'[{"day": "2025-07-29", "date": "2025-07-29", "note": "You''ve provided me with two identical drafts of the \"perfected\" SOP. This indicates a request for a final, meticulous review and consolidation of that single, comprehensive document. I will now perform a thorough analysis and refinement to ensure the ultimate clarity, precision, and integration of all the best elements from both original SOPs.", "progress": "You''ve provided me with two identical drafts of the \"perfected\" SOP. This indicates a request for a final, meticulous review and consolidation of that single, comprehensive document. I will now perform a thorough analysis and refinement to ensure the ultimate clarity, precision, and integration of all the best elements from both original SOPs.", "subtasks": {"total": 21}, "timeline": {"end": "2025-07-29T02:12:08.082+00:00", "start": "2025-07-28T22:13:42.913+00:00"}, "est_minutes": 238}]'::jsonb,NULL,NULL,NULL,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-28T06:56:32.522732+00:00','2026-06-28T06:56:32.522732+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('e9662cdb-749f-4607-817a-59a33242b392','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'documents','draft the Final Version of the SOP for Equipment Qualification and all changes applied as discussed previously.','completed','high','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045',NULL,'2025-08-04',ARRAY[]::text[],ARRAY['Annex 11','EU GMP Annex 15','Annex 05','Annex 09','est-hours-unverified','capture-v6','source:chat-extraction','Annex 13','Annex 07','consolidation-2026-06-28','Annex 08','Annex 01','Annex 02','Annex 03','ws:WS-EQ-QUAL','Annex 06','Annex 04','Annex 12','EudraLex','WHO TRS 961']::text[],'[{"day": "2025-08-06", "date": "2025-08-06", "note": "Of course. Here is the synthesized, perfect cohesive response for Section 6.6.2, merging the clarity, structure, and critical details from all four alternatives into a single, definitive version. This revision is both concise and comprehensive, using a clear, action-oriented structure that is easy to follow while ensuring full GxP compliance.", "progress": "Of course. Here is the synthesized, perfect cohesive response for Section 6.6.2, merging the clarity, structure, and critical details from all four alternatives into a single, definitive version. This revision is both concise and comprehensive, using a clear, action-oriented structure that is easy to follow while ensuring full GxP compliance.", "subtasks": {"total": 7}, "timeline": {"end": "2025-08-06T12:13:15.148+00:00", "start": "2025-08-06T09:12:11.111+00:00"}, "est_minutes": 181}]'::jsonb,NULL,NULL,NULL,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-28T06:56:32.522732+00:00','2026-06-28T06:56:32.522732+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('3ec3ce4a-d2b2-48af-8b74-8d17546a5b67','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'PP Quali SOP + 13 Annexes Syn-Fuz','analyze the two Draft SOPs and compare them in depth','completed','high','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045',NULL,'2025-08-04',ARRAY[]::text[],ARRAY['Annex 11','EU GMP Annex 15','Annex 05','Annex 09','est-hours-unverified','capture-v6','source:chat-extraction','Annex 13','Annex 07','consolidation-2026-06-28','Annex 08','Annex 01','Annex 02','Annex 03','ws:WS-EQ-QUAL','Annex 06','Annex 04','Annex 12','EudraLex','21 CFR Part 11','WHO TRS 961','Annex 15']::text[],'[{"day": "2025-08-05", "date": "2025-08-05", "note": "Yes, absolutely. To properly integrate Annex 13 (Equipment Lifecycle Record), the Annex 05 (Installation Qualification) template requires significant updates. The IQ is the critical control point where the physical as-built reality of the equipment is formally documented and verified against its design. Here is the final, redrafted version of Annex 05 - Template Installation Qualification (IQ).", "progress": "Yes, absolutely. To properly integrate Annex 13 (Equipment Lifecycle Record), the Annex 05 (Installation Qualification) template requires significant updates. The IQ is the critical control point where the physical as-built reality of the equipment is formally documented and verified against its design. Here is the final, redrafted version of Annex 05 - Template Installation Qualification (IQ).", "subtasks": {"total": 21}, "timeline": {"end": "2025-08-05T11:15:44.791+00:00", "start": "2025-07-29T02:44:09.92+00:00"}, "est_minutes": 10592}]'::jsonb,NULL,NULL,NULL,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-28T06:56:32.52273