e\u0434\u043d\u0438 \u0437\u0430 \u043e\u0434\u0440\u0436\u0443\u0432\u0430\u045a\u0435 \u043d\u0430 \u0441\u043b\u0435\u0434\u043b\u0438\u0432\u043e\u0441\u0442 \u0438 \u0443\u0441\u043e\u0433\u043b\u0430\u0441\u0435\u043d\u043e\u0441\u0442 \u0441\u043e GACP/GMP \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0434\u0438\u0442\u0435. \u041e\u0431\u0440\u0430\u0441\u0446\u0438\u0442\u0435 \u0441\u0435 \u0434\u0438\u0437\u0430\u0458\u043d\u0438\u0440\u0430\u043d\u0438 \u0434\u0430 \u0431\u0438\u0434\u0430\u0442 \u0458\u0430\u0441\u043d\u0438, \u0441\u0435\u043e\u043f\u0444\u0430\u0442\u043d\u0438 \u0438 \u043b\u0435\u0441\u043d\u0438 \u0437\u0430 \u043f\u043e\u043f\u043e\u043b\u043d\u0443\u0432\u0430\u045a\u0435 \u043e\u0434 \u0441\u0442\u0440\u0430\u043d\u0430 \u043d\u0430 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u043e\u0442, \u0441\u043e \u0446\u0435\u043b\u043e\u0441\u0435\u043d \u0434\u0432\u043e\u0458\u0430\u0437\u0438\u0447\u0435\u043d \u0444\u043e\u0440\u043c\u0430\u0442. --- **\u0414\u041e\u0414\u0410\u0422\u041e\u041a \u041d\u0410 \u0421\u0422\u0410\u041d\u0414\u0410\u0420\u0414\u041d\u0410 \u041e\u041f\u0415\u0420\u0410\u0422\u0418\u0412\u041d\u0410 \u041f\u041e\u0421\u0422\u0410\u041f\u041a\u0410** \u254f **STANDARD OPERATING PROCEDURE APPENDIX** **\u041d\u0430\u0441\u043b\u043e\u0432:** \u0424\u0430\u0437\u0430 \u043d\u0430 \u0440\u0430\u0437\u043c\u043d\u043e\u0436\u0443\u0432\u0430\u045a\u0435 - \u041e\u0431\u0440\u0430\u0441\u0446\u0438 \u0437\u0430 \u0435\u0432\u0438\u0434\u0435\u043d\u0446\u0438\u0458\u0430 \u254f **Title:** Propagation Phase - Log Sheet Template", "progress": "\u0412\u043e \u0440\u0435\u0434, \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043c. \u041f\u0440\u043e\u0434\u043e\u043b\u0436\u0443\u0432\u0430\u043c\u0435 \u0441\u043e \u043a\u0440\u0435\u0438\u0440\u0430\u045a\u0435 \u043d\u0430 \u0441\u043b\u0435\u0434\u043d\u0438\u043e\u0442 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0432\u043e \u0441\u0435\u0440\u0438\u0458\u04