INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('8f8caf26-b0d0-4fc6-a084-582f751638b6','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'Ingest HMA moisture-bias paper into DB3 RAG knowledge base','Curated the DB3_PP_CURRENT_unified Letta QMS knowledge base by RAG-ingesting the Nikolov et al. 2025 IOSR J. Pharm. paper Systemic Bias in In-Process Moisture Measurement Between HMA and Vacuum Drying Oven During Dry Cannabis Flower Production (file C15043338__HMA_Thesis.pdf). Extracted 6 pages / 26808 chars via PyMuPDF, chunked into 6 segments of about 800 words with 80-word overlap and provenance headers, base64-encoded and uploaded all 6 to source-89b764c4 via the Letta source_manager MCP. Remaining scope: de-duplicate against the same paper already ingested 2026-06-18 as two files (file-f0405f3c plus file-fe2d1416); one of the two ingestion sets should be deleted.','completed','normal','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045','8a1067a4-ef5b-444d-becb-f21b782d4c8c','2026-06-22',ARRAY['2026-06-27']::text[],ARRAY['academic','letta','rag','DB3','HMA','moisture','ingestion','dedup-needed','source:claude-code','capture-v5']::text[],'[{"date": "2026-06-27", "progress": "Extracted and chunked HMA paper into 6 chunks, base64-uploaded all 6 to DB3 source-89b764c4; all returned valid file IDs. Found pre-existing 2026-06-18 duplicate of two files; cleanup flagged.", "est_minutes": 30}]'::jsonb,NULL,'2026-06-27',0.5,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-27T06:08:27.149256+00:00','2026-06-28T06:46:22.699263+00:00') ON CONFLICT (id) DO NOTHING;
