INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('3f343fc4-ab4e-4056-8abf-3b55df98cc6f','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'Recreate PlantUML Diagrams in Purely Plant Visual Standard','User uploaded Diagrams.docx and Diagrams1.docx (13 rendered diagram images from prior tool use) revealing preferred visual style. Style palette extracted and documented: #000000 header with #9ACD32 lime text; #9ACD32 rounded activity boxes (RoundCorner 15, border 2px); #9575CD purple/mauve for decision diamonds and notes; bilingual MK⎸EN; #ADDC91/#C5E1A5 secondary nodes; #FFCDD2 for void/error. All 8 SOP diagrams recreated in puml_v2/. Key finding: PP visual style is a custom skinparam set — never use built-in PlantUML !theme directives for PP documents.','completed','high','draft','QC','8da0d112-2b4b-54f7-a779-42f8b0f62ed1','c8330a02-6fef-4d57-81c4-2a7396bbfb6f','2025-12-01',ARRAY['2025-11-28']::text[],ARRAY['diagrams','plantuml','puml','design-system','bilingual','sop-annexes','memorandum-control','pp-visual-standard','source:claude.ai','capture-v6']::text[],'[{"date": "2025-11-28", "progress": "8 .puml files in puml_v2/ recreated matching PP visual standard extracted from uploaded examples. Design palette and skinparam rules documented in memory.", "est_minutes": 10}]'::jsonb,NULL,'2025-11-28',0.17,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-28T02:33:58.165678+00:00','2026-06-28T06:46:22.699263+00:00') ON CONFLICT (id) DO NOTHING;
