INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('aa2f41c7-6585-4b93-9664-786d694150a7','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'Draft batch micro-sampling plan PP-QC-SP-001/26','Bilingual MK|EN sampling plan and execution protocol for representative sampling (600 g bRS) of 21 production batches held in secure storage, primarily for microbiological purity before sale. Includes per-batch N/n/target table (WHO TRS 929 Annex 4 r-plan, n=ceil(1.5*sqrt(N))), aseptic Grade D handling, pooling and split (micro 40 g, rRS 200 g, sRS 200 g, mRS 160 g) and ALCOA+ records. Remaining: confirm rRS/sRS/mRS contractual mapping, assign final document code (currently placeholder PP-QC-SP-001/26), add shelf-life/stability justification for the aged stock, and obtain QA approval and signatures.','ongoing','high','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045','8a1067a4-ef5b-444d-becb-f21b782d4c8c','2026-06-22',ARRAY['2026-06-24','2026-06-27']::text[],ARRAY['source:claude.ai','capture-v6','sampling-plan','microbiology','PP-QC-SP-001/26','bilingual','secure-warehouse']::text[],'[{"date": "2026-06-24", "progress": "Built 7-page bilingual plan with 21-batch N/n table totalling 1653,64 kg and 419 samples; verify PASS.", "est_minutes": 120}, {"date": "2026-06-27", "progress": "Removed tranche terminology, blanked personnel names for handwriting, added secure-warehouse location row, renamed file to Micro Purity.", "est_minutes": 30}]'::jsonb,NULL,NULL,2.5,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-28T02:37:13.767566+00:00','2026-06-28T06:46:22.699263+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('89847802-59a5-4cf0-90a1-6fbe3ac1658d','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'Determine Ph. Eur. sampling & micro reference for Cannabis flos','Regulatory determination that Ph. Eur. 2.8.20 (Herbal drugs: Sampling and sample preparation) governs container selection and chemical sample preparation for dried cannabis flower via monograph Cannabis flos 3028 with Herbal drugs 1433, but is unsuitable for microbiological sampling because its milling/quartering/sieving destroys micro integrity. Concluded that micro is sampled aseptically in Grade D and tested per Ph. Eur. 2.6.12/2.6.13 with route-based limits (5.1.8/5.1.4), and recommended the WHO TRS 929 Annex 4 r-plan n=ceil(1.5*sqrt(N)) on quality-risk grounds (ICH Q9). Remaining: keep the conclusions reflected in the controlled sampling plan and monitor the no-harmonised-inhalation-limit position.','completed','high','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045','8a1067a4-ef5b-444d-becb-f21b782d4c8c','2026-06-22',ARRAY['2026-06-24']::text[],ARRAY['source:claude.ai','capture-v6','microbiology','sampling','regulatory-analysis','ph-eur','Ph.Eur-2.8.20','WHO-TRS-929','ICH-Q9']::text[],'[{"date": "2026-06-24", "progress": "Resolved the 2.8.20 vs microbiology applicability question; set micro testing route 2.6.12/2.6.13 with 5.1.8/5.1.4 limits, the n=ceil(1.5*sqrt(N)) r-plan basis, and clarified Annex 19 / ICH Q7 retention sizing.", "est_minutes": 90}]'::jsonb,NULL,'2026-06-24',1.5,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-28T02:37:13.767566+00:00','2026-06-28T06:46:22.699263+00:00') ON CONFLICT (id) DO NOTHING;
