INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('4bc120c3-4b87-4c42-9cee-b4e0d3e9dcbe','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'Close CAPA RO_C158_006 sample 1203 faecal coliforms','DP-PPS002-PQ-MICRO-1203. Sample 1203 (29.04.2026, irrigation room) reported 80 CFU/100 ml faecal coliforms vs spec Absent. Open formal Deviation Report under QA_SOP_005 within 24 h; re-sample within 7 days with trained operator plus sterile equipment; inspect terminal distribution segment for biofilm; sanitization cycle (ozone or thermal 80 deg C times 60 min) if re-sample fails; review sampling SOP and operator training.','pending','critical','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045','b20c7c04-31d2-4a37-8a40-2c8b2c5e9fd2','2026-05-18',ARRAY[]::text[],ARRAY['PQ1','CAPA','RO_C158_006','faecal-coliforms','deficiency','DP-PPS002-PQ-MICRO-1203','sample-1203','EQP-PPS002','capture-v5','source:open-brain','gap-reconcile-2026-06-27']::text[],'[{"date": "2026-05-21", "progress": "Isolated event (1 of 9 days); all other days 0 CFU at same SL; no deviation or CAPA filed", "est_minutes": 0}]'::jsonb,NULL,NULL,0,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-27T06:04:31.214742+00:00','2026-06-28T06:46:22.699263+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('f5642a11-516b-4983-be8f-69bd4c261253','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'Revise A05/A06 pH spec for TR/RO water','DP-PPS002-PQ-PH-SYSTEMIC. A05 (TR) and A06 (RO) currently require pH 6.5-9.5 inherited from Pravilnik 183/2018 drinking-water rules; Ph. Eur. Purified Water sets no pH limit. Revise A05/A06 to remove the inappropriate lower bound, or accept pH 5.0-7.5 as process-control (not release) spec. After revision, 62 PQ1 findings reclassify as non-OOS. Route via change control with QA approval.','pending','high','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045','b20c7c04-31d2-4a37-8a40-2c8b2c5e9fd2','2026-05-18',ARRAY[]::text[],ARRAY['PQ1','spec-revision','A05','A06','pH','deficiency','DP-PPS002-PQ-PH-SYSTEMIC','change-control','capture-v5','source:open-brain','gap-reconcile-2026-06-27']::text[],'[{"date": "2026-05-21", "progress": "Identified across 62 TR/RO samples; spec revision proposed but not yet approved", "est_minutes": 0}]'::jsonb,NULL,NULL,0,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-27T06:04:31.214742+00:00','2026-06-28T06:46:22.699263+00:00') ON CONFLICT (id) DO NOTHING;
