INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('527386eb-fcba-4370-a0bb-3e624c49ec7a','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'Digitize PurelyPlant warehouse quarantine register (OCR + Letta RAG)','Convert the handwritten 53-entry PurelyPlant Warehouse Quarantine Register (paper log fields: No, Receipt date, Batch, PO, Product, Boxes) into a structured JSON record plus a Letta RAG archival-memory index. Enables search, traceability and downstream quarantine-label generation. Remaining scope: retry 10 of 53 Letta enriched passages that hit sub-agent context cap; allocate controlled SOP/register code (likely WHSOP_001 family); decide label template split for the two product types; merge branch claude/warehouse-quarantine-ocr-aoHul to main.','ongoing','high','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045','8a1067a4-ef5b-444d-becb-f21b782d4c8c','2026-06-22',ARRAY['Mon','Thu']::text[],ARRAY['warehouse','quarantine','register','ocr','json','letta','rag','WHSOP','source:claude-code','capture-v5']::text[],'[{"date": "2026-05-25", "progress": "Initial OCR of 8 jpegs into 53-entry JSON; 53 base Letta passages created (commit 6b2c1fa)", "est_minutes": 90}, {"date": "2026-06-25", "progress": "Enriched JSON with product_name, product_type (entries 47-53 Dry Chopped Medical Cannabis Biomass; rest Dry Cannabis Flower), box counts, strain_code_map; fixed 2 OCR errors (CJ092501 was GJ; OPM092501 was OPH); 43 of 53 enriched Letta passages written before sub-agent context cap; strain distribution analysis produced (commit e31f19c)", "est_minutes": 22}]'::jsonb,NULL,NULL,1.87,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-27T06:14:18.153924+00:00','2026-06-28T06:46:22.699263+00:00') ON CONFLICT (id) DO NOTHING;
