INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('8ef4082c-0b8e-4754-9275-9eb18c152404','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'Build PDF merger script for GMP label batches','Python utility (scripts/docx_to_merged_pdf.py) to batch-convert all .docx label files in a folder to PDF using Microsoft Word via docx2pdf, then merge into a single PDF using pypdf. Pre-configured for two GMP-regulated label sets in LABEL_PREP: Quarantine Labels and Released4Storage Labels (Generated_193_per_page). Remaining: user runs pip install docx2pdf pypdf on Windows and executes the script; verify label pagination and merge order match GMP-release requirements.','completed','normal','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045','8a1067a4-ef5b-444d-becb-f21b782d4c8c','2026-06-22',ARRAY['2026-06-27']::text[],ARRAY['label-prep','quarantine-labels','released4storage','pdf-merger','docx2pdf','pypdf','qms-tooling','QASOP031','LABEL_PREP','source:claude-code','capture-v5']::text[],'[{"date": "2026-06-27", "progress": "Generated scripts/docx_to_merged_pdf.py (docx2pdf + pypdf); committed to branch claude/amazing-bell-v2nMJ (commit 172898b); draft PR #2 opened on 3p4e/ACME_SOP. Script batch-mode pre-configured for Quarantine Labels and Released4Storage Labels folders, CLI mode available for ad-hoc runs.", "est_minutes": 20}]'::jsonb,NULL,'2026-06-27',0.33,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-27T06:18:41.660659+00:00','2026-06-28T06:46:22.699263+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO tasks(id,org_id,user_id,parent_id,title,description,status,priority,workflow_state,department,department_id,week_id,week_start,days,tags,progress_notes,due_date,completed_date,estimated_hours,created_by,created_at,updated_at) VALUES ('68858452-c871-4381-bcaa-81ebca785457','a0a0a0a0-0000-4000-8000-000000000001','a0a0a0a0-0000-4000-8000-0000000000b1',NULL,'Embed mandatory PP header into pp-document-suite skill','The unified pp-document-suite document engine was missing the mandatory Purely Plant running header, footer and logo on the SOP build path (a regression from merging the four legacy skills into one). Embedded the base-template mechanism (PP_BASE_TEMPLATE.docx plus apply_pp_header and wipe_body; new_sop and new_annex now start from the template), documented the header, footer and A4 page geometry in SKILL.md and formatting_specs, repackaged pp-document-suite.skill, and captured a content-fidelity no-impoverishment instruction for the next agent. Remaining: re-import the skill via Settings then Capabilities to activate it in the running skill.','completed','high','draft','Quality Control','b3da4461-e265-5591-990a-aa141741b045','8a1067a4-ef5b-444d-becb-f21b782d4c8c','2026-06-22',ARRAY['Saturday']::text[],ARRAY['pp-document-suite','skill','header','QMS-tooling','source:cowork','capture-v5']::text[],'[{"date": "2026-06-27", "progress": "Ported the legacy template-header logic into the unified engine; smoke-tested that new_sop with a code emits the leaf logo, bilingual document name, code, version and Page X of Y with zero manual steps; repackaged the skill and wrote the content-fidelity rule.", "est_minutes": 75}]'::jsonb,NULL,'2026-06-27',1.25,'a0a0a0a0-0000-4000-8000-0000000000b1','2026-06-27T22:29:29.827376+00:00','2026-06-28T06:46:22.699263+00:00') ON CONFLICT (id) DO NOTHING;
